    String LOGGED_IN_USER_NAME = "David.Anderson";
    String ACCESS_ITEM = "c0a8567687ed1b168187ed8c82f1041e";
    String[] IDENTITY_IDS = {"c0a8567687ed1dd28187ed8e06ff0047"};
    String[] OTHER_ADDED_ROLES = {};
    String QUICK_LINK = "Request Access";

    /*
     * Customer deets
    String LOGGED_IN_USER_NAME = "David.Anderson";
